import React, { useState } from 'react';
import { LOGO_SQUARE } from '../mock/data';
import { login, activate, issueActivation } from '../mock/store';

export default function Login({ onLogin }) {
  const [mode, setMode] = useState('login');
  const [uid, setUid] = useState('');
  const [pw, setPw] = useState('');
  const [pw2, setPw2] = useState('');
  const [code, setCode] = useState('');
  const [remember, setRemember] = useState(false);
  const [msg, setMsg] = useState(null);

  const doLogin = (e) => {
    e && e.preventDefault();
    setMsg(null);
    try {
      const u = login(uid, pw);
      onLogin(u);
    } catch (err) {
      setMsg({ type: 'danger', text: err.message });
    }
  };

  const doActivate = (e) => {
    e && e.preventDefault();
    setMsg(null);
    if (pw !== pw2) return setMsg({ type: 'danger', text: 'Пароли не совпадают' });
    if (pw.length < 4) return setMsg({ type: 'danger', text: 'Пароль слишком короткий (минимум 4 символа)' });
    try {
      const u = activate(uid, code, pw);
      onLogin(u);
    } catch (err) {
      setMsg({ type: 'danger', text: err.message });
    }
  };

  const demoIssue = () => {
    if (!uid) return setMsg({ type: 'danger', text: 'Введите Discord User ID' });
    const c = issueActivation(uid);
    setCode(c);
    setMsg({ type: 'good', text: `Одноразовый код выдан: ${c}` });
  };

  return (
    <div className="login-wrap">
      <div className="login-card">
        <img className="login-logo" src={LOGO_SQUARE} alt="RRT" />
        <h1>RAPID RESPONSE TEAM</h1>
        <p className="login-sub">Закрытый портал подразделения</p>

        <div className="tabs">
          <button
            className={mode === 'login' ? 'active' : ''}
            onClick={() => { setMode('login'); setMsg(null); }}
          >
            Вход
          </button>
          <button
            className={mode === 'activate' ? 'active' : ''}
            onClick={() => { setMode('activate'); setMsg(null); }}
          >
            Первый вход
          </button>
        </div>

        {msg && <div className={`notice ${msg.type}`}>{msg.text}</div>}

        {mode === 'login' ? (
          <form onSubmit={doLogin}>
            <div className="field">
              <label>Discord User ID</label>
              <input
                value={uid}
                onChange={(e) => setUid(e.target.value)}
                autoComplete="username"
                placeholder="Ваш ID из Discord"
                data-testid="login-id-input"
              />
            </div>
            <div className="field">
              <label>Пароль</label>
              <input
                type="password"
                value={pw}
                onChange={(e) => setPw(e.target.value)}
                autoComplete="current-password"
                data-testid="login-password-input"
              />
            </div>
            <label className="check-row">
              <input
                type="checkbox"
                checked={remember}
                onChange={(e) => setRemember(e.target.checked)}
              />
              Запомнить меня
            </label>
            <button className="btn red wide" type="submit" data-testid="login-submit-button">
              Войти
            </button>
          </form>
        ) : (
          <form onSubmit={doActivate}>
            <div className="notice" style={{ marginBottom: 12 }}>
              Первый вход: Discord User ID + одноразовый код от Штаба. После активации код становится недействительным.
            </div>
            <div className="field">
              <label>Discord User ID</label>
              <input
                value={uid}
                onChange={(e) => setUid(e.target.value)}
                data-testid="activate-id-input"
              />
            </div>
            <div className="field">
              <label>Одноразовый код</label>
              <input
                value={code}
                onChange={(e) => setCode(e.target.value)}
                placeholder="ABC123"
                data-testid="activate-code-input"
              />
            </div>
            <div className="field">
              <label>Новый пароль</label>
              <input
                type="password"
                value={pw}
                onChange={(e) => setPw(e.target.value)}
                autoComplete="new-password"
                data-testid="activate-password-input"
              />
            </div>
            <div className="field">
              <label>Повторите пароль</label>
              <input
                type="password"
                value={pw2}
                onChange={(e) => setPw2(e.target.value)}
                autoComplete="new-password"
                data-testid="activate-password-confirm-input"
              />
            </div>
            <button className="btn red wide" type="submit" data-testid="activate-submit-button">
              Активировать
            </button>
            <button
              type="button"
              className="btn ghost wide"
              style={{ marginTop: 8 }}
              onClick={demoIssue}
              data-testid="activate-demo-code-button"
            >
              Выдать демо-код (только для Штаба)
            </button>
          </form>
        )}
      </div>
    </div>
  );
}